import { SUBAGENT_MODEL } from "./config.ts";
import { trace } from "./diagnostics.ts";
import { chat } from "./groq.ts";
import { logger } from "./logger.ts";
import type { AgentState } from "./agent.ts";

export const AUTO_COMPACT_THRESHOLD = 90_000;

export async function compactHistory(state: AgentState): Promise<string> {
  if (state.messages.length < 4) return "Nothing to compact yet.";
  const keepTail = state.messages.slice(-2);
  const toSummarize = state.messages.slice(0, -2);
  const transcript = toSummarize
    .map((m) => `[${m.role}]\n${m.content.slice(0, 4000)}`)
    .join("\n\n");

  const res = await chat(
    [
      {
        role: "system",
        content:
          "Summarize this agent conversation for context compaction. Preserve: the user's goals, decisions made, files created/modified with their paths, key facts discovered, current task state, and anything still unfinished. Be dense and factual. Output only the summary.",
      },
      { role: "user", content: transcript.slice(0, 100_000) },
    ],
    { model: SUBAGENT_MODEL, maxTokens: 2048 },
  );

  const before = state.messages.length;
  state.messages = [
    {
      role: "user",
      content: `[Context was compacted. Summary of the conversation so far:]\n\n${res.content}`,
    },
    { role: "assistant", content: "Understood — continuing from that summary." },
    ...keepTail,
  ];
  state.lastPromptTokens = 0;
  logger.info("compact.done", { before, after: state.messages.length });
  trace("compact", { before, after: state.messages.length });
  return `Compacted ${before} messages → ${state.messages.length}.`;
}
